sys_script_include.script:
var ClearLaptopOwner = Class.create();
ClearLaptopOwner.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    clearOwner: function() {
        var result = {
            'answer': 'NG'
        };
        var sn = this.getParameter('sysparm_sn_number');
        var rs = new GlideRecord('x_1755490_asset_0_asset_stock');
        rs.addQuery('serial_number', sn);
        rs.query();
        if (rs.next()) {
            //update the record.
            rs.assigned = false;
			//clear reference filed method is setValue
            rs.setValue('owner','');
			//rs.setValue('owner->sys_id','');
            //rs.setDisplayValue('owner','');
			rs.update();
            //rs.updateWithReferences();
			result = {
                'answer': 'OK'
            };

        }
        return JSON.stringify(result);
    },
    type: 'ClearLaptopOwner'
});
